USE sql_notes;
SELECT AVG(marks_obtained) AS avg_m FROM marks;
SELECT name FROM students WHERE student_id IN (SELECT student_id FROM enrollments WHERE course_id=1);
SELECT s.name,m.marks_obtained FROM students s JOIN enrollments e ON s.student_id=e.student_id JOIN marks m ON m.enrollment_id=e.enrollment_id WHERE m.marks_obtained>(SELECT AVG(marks_obtained) FROM marks);
SELECT DISTINCT marks_obtained FROM marks ORDER BY marks_obtained DESC LIMIT 1 OFFSET 1;
SELECT s.name FROM students s JOIN (SELECT student_id,COUNT(*) c FROM enrollments GROUP BY student_id) t ON t.student_id=s.student_id WHERE t.c>1;
SELECT s.name FROM students s WHERE EXISTS (SELECT 1 FROM enrollments e WHERE e.student_id=s.student_id);
SELECT name FROM students WHERE dept_id=1 UNION SELECT name FROM students WHERE enrollment_year=2023;
SELECT c.course_name,s.name,m.marks_obtained FROM students s JOIN enrollments e ON s.student_id=e.student_id JOIN courses c ON e.course_id=c.course_id JOIN marks m ON m.enrollment_id=e.enrollment_id WHERE m.marks_obtained=(SELECT MAX(m2.marks_obtained) FROM enrollments e2 JOIN marks m2 ON m2.enrollment_id=e2.enrollment_id WHERE e2.course_id=e.course_id);
SELECT s.name,c.course_name,m.marks_obtained FROM students s JOIN enrollments e ON s.student_id=e.student_id JOIN courses c ON e.course_id=c.course_id JOIN marks m ON m.enrollment_id=e.enrollment_id WHERE m.marks_obtained>(SELECT AVG(m2.marks_obtained) FROM enrollments e2 JOIN marks m2 ON m2.enrollment_id=e2.enrollment_id WHERE e2.student_id=s.student_id);
SELECT s.name FROM students s WHERE NOT EXISTS (SELECT 1 FROM enrollments e WHERE e.student_id=s.student_id);
SELECT COUNT(*) FROM marks WHERE marks_obtained > ANY (SELECT m2.marks_obtained FROM marks m2 JOIN enrollments e2 ON m2.enrollment_id=e2.enrollment_id WHERE e2.course_id=3);
SELECT COUNT(*) FROM marks WHERE marks_obtained > ALL (SELECT m2.marks_obtained FROM marks m2 JOIN enrollments e2 ON m2.enrollment_id=e2.enrollment_id WHERE e2.course_id=3);
SELECT COUNT(*) FROM (SELECT student_id FROM enrollments WHERE course_id=1 UNION ALL SELECT student_id FROM enrollments WHERE course_id=3) t;
SELECT s.name FROM students s WHERE s.student_id IN (SELECT student_id FROM enrollments WHERE course_id=1) AND s.student_id IN (SELECT student_id FROM enrollments WHERE course_id=3);
SELECT s.name FROM students s JOIN enrollments e ON s.student_id=e.student_id WHERE e.course_id=1 AND NOT EXISTS (SELECT 1 FROM enrollments x WHERE x.student_id=s.student_id AND x.course_id=3);
SELECT e.course_id,MAX(m.marks_obtained) AS second_max FROM enrollments e JOIN marks m ON m.enrollment_id=e.enrollment_id WHERE m.marks_obtained<(SELECT MAX(m2.marks_obtained) FROM enrollments e2 JOIN marks m2 ON m2.enrollment_id=e2.enrollment_id WHERE e2.course_id=e.course_id) GROUP BY e.course_id;
SELECT s.name,AVG(m.marks_obtained) AS a FROM students s JOIN enrollments e ON s.student_id=e.student_id JOIN marks m ON m.enrollment_id=e.enrollment_id GROUP BY s.student_id,s.name HAVING AVG(m.marks_obtained)>(SELECT AVG(marks_obtained) FROM marks);
SELECT name FROM students WHERE student_id=(SELECT student_id FROM enrollments WHERE enrollment_id=(SELECT enrollment_id FROM marks ORDER BY marks_obtained DESC LIMIT 1));
SELECT DISTINCT s.name FROM students s JOIN enrollments e ON s.student_id=e.student_id WHERE e.course_id=1;
SELECT name FROM students WHERE student_id NOT IN (1,2,NULL);
SELECT s.name,c.course_name FROM students s LEFT JOIN enrollments e ON s.student_id=e.student_id LEFT JOIN courses c ON e.course_id=c.course_id UNION SELECT s.name,c.course_name FROM students s RIGHT JOIN enrollments e ON s.student_id=e.student_id RIGHT JOIN courses c ON e.course_id=c.course_id;
SELECT s.name,m.marks_obtained,(SELECT COUNT(*)+1 FROM marks m2 WHERE m2.marks_obtained>m.marks_obtained) AS rank_no FROM students s JOIN enrollments e ON s.student_id=e.student_id JOIN marks m ON m.enrollment_id=e.enrollment_id ORDER BY rank_no;
